      "speaker": "caller",
      "text": "Hello."
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "मैं देख पा रही हूं आपको RO capacity 1000 litre per hour ही चाहिए ना?"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "Hello क्या आप अभी line पे हैं?"
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "हाँ जी।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "मैं देख पा रही हूं।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "आपको RO capacity 1000 liters per hour ही चाहिए ना?"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "जी जी।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "अब materials के बारे में बात कर लेते हैं तो आपको FRP, stainless steel या कुछ और चाहिए?"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "मैं वही चाहिए।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "क्षमा कीजिए मैं समझ नहीं पाई।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "आप material में FRP, stainless steel या कोई और options prefer करेंगे?"
    },
    {
      "i": 18,
      "speaker": "caller",
      "text": "अरे जो double piece वाला है ना वही चाहिए।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "ठीक है मैं समझ गई।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "अब seller आपसे इस बारे में और detail में बात कर लेंगे।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "बस कुछ और details confirm कर दीजिए।"
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "detail मेरा मोटिहार जिला से है।"
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "आप अपनी city और state भी बता दीजिए please।"
    },
    {
      "i": 25,
      "speaker": "caller",
      "text": "तो रशीद चमन भाई।"
    },
    {
      "i": 26,
      "speaker": "bot",
      "text": "क्षमा कीजिए मुझे समझ नहीं आया।"
    },
    {
      "i": 27,
      "speaker": "bot",
      "text": "क्या आप अपनी city और state का नाम बता सकते हैं?"
    },
    {
      "i": 28,
      "speaker": "caller",
      "text": "नहीं बोल रहे हैं मोतिहारी जिला।"
    },
    {
      "i": 29,
      "speaker": "bot",
      "text": "आप मोतियारा गुजरात से बोल रहे हैं ना?"
    }
  ]
